        )
        if existing:
            raise AppException(409, f"Room name '{payload.name}' already exists", "Conflict")

        room = RoomModel(
            name=payload.name,
            room_type=payload.room_type.value,
            capacity=payload.capacity,
            active=payload.active if payload.active is not None else True,
            is_deleted=False,
        )
        db.add(room)
        db.commit()
        db.refresh(room)
        return room
